INSERT INTO public.tools_catalog (id, name, description, category, tool_types, source, is_live, is_premium, is_free, dedicated_route, display_order, extra_categories)
VALUES
  ('personal-tutor', 'Personal Tutor', 'A patient one-to-one tutor for any subject and class: explains step by step, asks questions back, and ends with notes and practice.', 'For Students', ARRAY['Tutoring', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('jee-neet-and-cuet-prep-planner', 'JEE, NEET and CUET Prep Planner', 'A study plan for JEE, NEET or CUET built from your scores: chapter priorities, daily timetable, mock test plan and revision cycles.', 'For Students', ARRAY['Entrance Exams', 'Study Plans'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('mock-test-analyser', 'Mock Test Analyser', 'Upload your mock test result or answer sheet to find where marks are lost: by chapter, type of mistake and time, with a fix plan.', 'For Students', ARRAY['Test Analysis', 'Analytics Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('revision-kit-maker', 'Revision Kit Maker', 'Upload a chapter or notes to get a full revision kit: summary notes, mind map, formulas, flashcards, MCQs and exam-style questions.', 'For Students', ARRAY['Revision', 'Study Tools'], 'featured', true, false, false, NULL, 0, ARRAY['For Teachers']),
  ('homework-explainer', 'Homework Explainer', 'Snap a homework question and get it explained step by step at your class level, with the concept, a similar practice question and tips.', 'For Students', ARRAY['Homework Help', 'Study Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('answer-writing-evaluator', 'Answer Writing Evaluator', 'Upload handwritten or typed answers for UPSC, board or university exams and get marks, examiner-style comments and a model answer.', 'For Students', ARRAY['Answer Writing', 'Assessment'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('foreign-language-coach', 'Foreign Language Coach', 'Learn French, German, Spanish, Japanese, Korean or Arabic by speaking: role-plays, gentle corrections and a lesson summary.', 'For Students', ARRAY['Languages', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('spoken-english-coach', 'Spoken English Coach', 'Improve spoken English for interviews, work and daily life: real conversations, corrections, better phrases and fluency tracking.', 'For Students', ARRAY['English', 'Coaching'], 'featured', true, false, false, NULL, 0, ARRAY['Jobs & Careers']),
  ('science-project-builder', 'Science Project Builder', 'Plan a school science project or exhibition model: idea options, materials, step-by-step build, experiment log, report and viva questions.', 'For Students', ARRAY['Projects', 'Science'], 'featured', true, false, false, NULL, 0, ARRAY['For Teachers']),
  ('literature-review-builder', 'Literature Review Builder', 'Upload research papers to get summaries, a comparison matrix, themes, gaps and a draft literature review with proper citations.', 'For Students', ARRAY['Research', 'Academic Writing'], 'featured', true, false, false, NULL, 0, ARRAY['Research']),
  ('thesis-studio', 'Thesis Studio', 'Shape your dissertation through a guided conversation: research question, chapter plan, methodology, timeline and a first-chapter draft.', 'For Students', ARRAY['Academic Writing', 'Research'], 'featured', true, false, false, NULL, 0, ARRAY['Research']),
  ('teacher-unit-studio', 'Teacher Unit Studio', 'Plan a full teaching unit: lesson plans for each period, activities, worksheets, assessments with rubrics and differentiation.', 'For Teachers', ARRAY['Lesson Planning', 'Teaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('question-paper-generator', 'Question Paper Generator', 'Create a full question paper from your chapters and blueprint: sections, marks, difficulty mix, answer key and marking scheme.', 'For Teachers', ARRAY['Assessment', 'Teaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('report-card-remarks-writer', 'Report Card Remarks Writer', 'Upload your class marks list to get personalised, kind and specific report card remarks for every student, plus parent meeting notes.', 'For Teachers', ARRAY['Teaching', 'Writing'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('kids-learning-path', 'Kids Learning Path', 'A 12-week learning plan for your child''s age and interests: weekly goals, daily 30-minute activities, reading list and progress checks.', 'For Students', ARRAY['Kids', 'Learning'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('olympiad-trainer', 'Olympiad Trainer', 'Train for maths, science or reasoning olympiads with challenging problems at your level, hints, full solutions and a topic plan.', 'For Students', ARRAY['Olympiad', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('stream-and-career-test', 'Stream and Career Test', 'For Class 9–12 students: answer questions on interests, strengths and values to get a stream fit, career options and a roadmap.', 'For Students', ARRAY['Career Guidance', 'Assessment'], 'featured', true, false, false, NULL, 0, ARRAY['Jobs & Careers']),
  ('newspaper-to-upsc-notes', 'Newspaper to UPSC Notes', 'Upload newspaper pages or editorials to get UPSC-ready notes: syllabus mapping, background, both sides, Mains questions and MCQs.', 'For Students', ARRAY['UPSC', 'Current Affairs'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('coaching-centre-kit', 'Coaching Centre Kit', 'Launch or grow a tuition or coaching centre: courses and fees, batch plan, admission funnel, parent communication, ads and policies.', 'For Teachers', ARRAY['Education Business', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy', 'Marketing & Sales']),
